def capped_height(original):
    if original.get('st_height_method') != 'forward_regular_corner_v1':
        raise ValueError('Expected the qualified forward regular corner height interface')
    tree = original.copy(); tree.name = 'Depth-limited profile / '+original.name
    g = _graph(tree)
    inp, = [node for node in tree.nodes if node.type == 'GROUP_INPUT']
    fraction = _store_node(tree, 'st_ch_fraction').inputs['Value'].links[0].from_socket
    consumers = [link.to_socket for link in fraction.links]
    q = c.named(g, ATTRIBUTE); v = c.bounded(g, c.named(g, 'st_cq_v'))
    qsafe = g.math('MAXIMUM', q, .500001)  # Arithmetic only; validity below rejects q<=.5.
    join = (2.*qsafe-1.)/qsafe
    value = c.choose(g, g.math('LESS_THAN', v, join),
                     1.-qsafe*qsafe/(2.*qsafe-1.)*v*v, 2.*qsafe*(1.-v))
    chart, _, _ = g.separate(c.named(g, 'st_cq_key', 'FLOAT_VECTOR'))
    band = g.math('GREATER_THAN', chart, .5)
    exists = g.node('GeometryNodeInputNamedAttribute'); exists.data_type = 'FLOAT'
    exists.inputs['Name'].default_value = ATTRIBUTE
    active = c.V(g, exists.outputs['Exists'])*band
    proposed = c.choose(g, active*g.math('LESS_THAN', q, 1.), value, fraction)
    for socket in consumers:
        g.bind(proposed, socket)
    valid_store = _store_node(tree, 'st_ch_valid')
    old_valid = valid_store.inputs['Value'].links[0].from_socket
    consumers = [link.to_socket for link in old_valid.links]
    mouths = inp.outputs['Mouths']
    equal_crowns = g.math('LESS_THAN', c._stat(g, mouths, c.named(g, 'st_cj_rise'), 'Max')
                          -c._stat(g, mouths, c.named(g, 'st_cj_rise'), 'Min'), 1e-7)
    family = c.choose(g, g.math('LESS_THAN', q, 1.), equal_crowns, True, 'BOOLEAN')
    feasible = c._stat(g, inp.outputs['Geometry'], c.choose(g, active,
        g.math('GREATER_THAN', q, .5)*g.math('LESS_THAN', q, 1.000001)*family, True, 'BOOLEAN'))
    valid = c.V(g, old_valid)*feasible
    for socket in consumers:
        g.bind(valid, socket)
    tree['st_height_profile_experiment'] = 'physical_depth_capped_quadratic_v1'
    return tree


