def depth_floor(*, minimum_ratio=.75, trigger_ratio=.500001, oriented=False):
    """Nearest feasible guide point against both adjacent curb halfplanes.

    This bounded layout proposal runs only when an already corrected full band
    lacks the depth required by the existing capped profile. It changes no
    boundary or entrance samples. Cell, seam, profile and boundary acceptance
    remain the responsibility of the unchanged complete caller.
    """
    if not .5 < minimum_ratio < 1.:
        raise ValueError('Depth proposal must leave room for the capped profile')
    if not .5 < trigger_ratio < 1. or (trigger_ratio > minimum_ratio and trigger_ratio != .500001):
        raise ValueError('Depth trigger must be feasible and no larger than the requested depth')
    name = f'Prochitecture Streets / Infeasible corner depth layout v1 / {minimum_ratio:g}'
    if trigger_ratio != .500001:name += f' / Trigger {trigger_ratio:.12g}'
    if oriented:name += ' / Inward halfplanes v2'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    for key in ('Samples', 'Mouths'):
        g.socket(key, 'NodeSocketGeometry')
    g.socket('Rows', 'NodeSocketInt'); g.socket('Eligible', 'NodeSocketBool')
    g.socket('Samples', 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Applied', 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    source = inp.outputs['Samples']; mouths = inp.outputs['Mouths']
    initial = g.node('GeometryNodeGroup', 'Check the existing physical depth first')
    initial.node_tree = depth_samples(oriented=oriented)
    for key in ('Samples', 'Mouths', 'Rows'):
        g.bind(inp.outputs[key], initial.inputs[key])
    need = c.V(g, inp.outputs['Eligible'])*g.math('LESS_THAN',
        c._stat(g, initial.outputs['Samples'], c.named(g, ATTRIBUTE), 'Min'), trigger_ratio)
    n = c.V(g, inp.outputs['Rows']); pitch = n+1.
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    owner = g.math('FLOOR', index/pitch); row = g.math('MODULO', index, pitch)
    first = owner*pitch; last = first+n
    point = lambda at: c._vec(g, c._sample(g, source, g.position(), at, 'FLOAT_VECTOR'))
    outer = lambda at: c._vec(g, c._read(g, source, '_lc_outer', at, 'FLOAT_VECTOR'))
    previous = first+g.math('MAXIMUM', row-1., 0.)
    following = first+g.math('MINIMUM', row+1., n)
    delta = c._sub(point(index), outer(index))
    normals = []
    for tangent in (c._unit(g, c._sub(outer(index), outer(previous))),
                    c._unit(g, c._sub(outer(following), outer(index)))):
        normal = (-tangent[1], tangent[0])
        # The ordered curb runs counterclockwise around the pavement. Its
        # interior is always on the left. Choosing the sign from the proposed
        # guide itself can deepen an already inverted band outside the curb.
        if not oriented:
            sign = c.choose(g, g.math('LESS_THAN', c._dot(normal, delta), 0.), -1., 1.)
            normal=c._scale(normal,sign)
        normals.append(normal)
    width = g.math('MINIMUM', c._length(g, c._sub(point(first), outer(first))),
                   c._length(g, c._sub(point(last), outer(last))))
    bounds = [minimum_ratio*width-c._dot(normal, delta) for normal in normals]
    a, b = normals; det = c._cross(a, b)
    safe_det = c.choose(g, g.math('LESS_THAN', det, 0.), -1., 1.)*g.math('MAXIMUM',
        g.math('ABSOLUTE', det), 1e-12)
    intersection = ((bounds[0]*b[1]-bounds[1]*a[1])/safe_det,
                    (a[0]*bounds[1]-b[0]*bounds[0])/safe_det)
    # In two dimensions the closest point lies at the original point, on one
    # active constraint, or at their intersection. No iterative solver needed.
    proposals = [(c._scale(a, 0.), True)]
    proposals += [(c._scale(normal, bound), True) for normal, bound in zip(normals, bounds)]
    proposals.append((intersection, g.math('GREATER_THAN', g.math('ABSOLUTE', det), 1e-8)))
    best = (0., 0.); best_cost = 1e30; found = 0.
    for shift, usable in proposals:
        feasible = usable
        for normal, bound in zip(normals, bounds):
            feasible *= 1.-g.math('LESS_THAN', c._dot(normal, shift), bound-1e-7)
        cost = c._dot(shift, shift)
        select = feasible*g.math('LESS_THAN', cost, best_cost)
        best = tuple(c.choose(g, select, p, q) for p, q in zip(shift, best))
        best_cost = c.choose(g, select, cost, best_cost)
        found = g.math('MAXIMUM', found, feasible)
    if oriented:
        # An exact intersection can round just outside one halfplane in
        # float32. If every nearest-point proposal failed, try a strictly
        # inward point instead of weakening the feasibility tolerance. Keep
        # every already feasible result bit-for-bit unchanged.
        margin=8.*1.1920928955078125e-7*(width+g.math('ABSOLUTE',bounds[0])+g.math('ABSOLUTE',bounds[1]))
        inside=c._add(intersection,c._scale(c._add(a,b),margin))
        feasible=g.math('GREATER_THAN',g.math('ABSOLUTE',det),1e-8)
        for normal,bound in zip(normals,bounds):
            feasible*=1.-g.math('LESS_THAN',c._dot(normal,inside),bound-1e-7)
        select=(1.-found)*feasible
        best=tuple(c.choose(g,select,p,q) for p,q in zip(inside,best))
        best_cost=c.choose(g,select,c._dot(inside,inside),best_cost)
        found=g.math('MAXIMUM',found,feasible)
    nxt = g.math('MODULO', owner+1., c._count(g, mouths))
    eligible = 1.-g.math('COMPARE', c._read(g, mouths, 'st_cj_half', owner, 'INT'), -1.)
    eligible *= 1.-g.math('COMPARE', c._read(g, mouths, 'st_cj_half', nxt, 'INT'), 1.)
    eligible *= g.math('GREATER_THAN', row, .5)*g.math('LESS_THAN', row, n-.5)
    # Limit this proposal's movement as well as the profile it makes possible.
    # A rejected proposal retains its old point and remains subject to the
    # original depth feasibility check; it is never made valid by clamping q.
    accepted = eligible*found*(1.-g.math('GREATER_THAN', best_cost, width*width))
    x, y, z = g.separate(g.position())
    moved = g.setpos(source, c.choose(g, accepted, g.xyz(x+best[0], y+best[1], z),
                                    g.position(), 'VECTOR'))
    g.bind(c.choose(g, need, moved, source, 'GEOMETRY'), out.inputs['Samples'])
    g.bind(need, out.inputs['Applied'])
    g.g['st_corner_depth_floor'] = minimum_ratio
    if oriented:g.g['st_oriented_profile_depth']=2
    return g.g


def install_oriented_depth(roots):
    """Upgrade existing depth readers/proposals in a disposable saved library.

    All physical curbs and complete acceptance guards stay in place. Retain
    canonical caller names and non-evaluated constructor references, which the
    installed authoring path also uses. Newly created dependencies are excluded
    from the collected call list, avoiding accidental recursive replacement.
    """
    pending=list(roots);seen=set();requests=[]
    while pending:
        tree=pending.pop()
        if tree in seen:continue
        seen.add(tree)
        pending.extend(value for value in tree.values() if isinstance(value,bpy.types.NodeTree))
        for node in tree.nodes:
            if node.type!='GROUP' or node.node_tree is None:continue
            child=node.node_tree;pending.append(child)
            if child.get('st_oriented_profile_depth'):continue
            if child.name.startswith('Prochitecture Streets / Corner profile physical depth v1'):
                requests.append((tree,node.name,child,'depth'))
            elif child.name.startswith('Prochitecture Streets / Infeasible corner depth layout v1'):
                requests.append((tree,node.name,child,'floor'))
    replacements={};changes=[]
    for tree,name,child,kind in requests:
        if child not in replacements:
            if kind=='depth':replacement=depth_samples(oriented=True)
            else:
                trigger=float(child.name.split(' / Trigger ')[1].split(' / ')[0]) if ' / Trigger ' in child.name else .500001
                replacement=depth_floor(minimum_ratio=float(child['st_corner_depth_floor']),
                                        trigger_ratio=trigger,oriented=True)
            replacements[child]=replacement
        assign_group(tree.nodes[name],replacements[child])
        changes.append(dict(caller=tree.name,node=name,original=child.name,replacement=replacements[child].name))
    if not changes:raise ValueError('No unsigned corner-depth readers or proposals found')
    return changes


def reserved_slope_height(original):
    """Reserve radial slope room for tangential variation in compressed bands.

    q_eff=q*(1-r*4*q*(1-q)) retains q=1 exactly, so incoming full profiles
    remain untouched. It changes the interior profile shape, not its crest or
    curb height. The original feasibility guard also sees q_eff and must still
    reject q_eff<=.5. Full XY gradient qualification remains independent.
    """
    if original.get('st_height_profile_experiment') != 'physical_depth_capped_quadratic_v1':
        raise ValueError('Expected the existing physical-depth capped profile')
    if original.get('st_corner_profile_slope_reserve'):
        raise ValueError('Corner slope reserve already installed')
    tree = original.copy(); tree.name = 'Reserved corner slope / '+original.name
    g = _graph(tree)
    reads = [node for node in tree.nodes if node.bl_idname == 'GeometryNodeInputNamedAttribute'
             and node.inputs['Name'].default_value == ATTRIBUTE and node.data_type == 'FLOAT']
    if not reads:
        raise ValueError('Capped height has no physical-depth field')
    reserve = c.named(g, SLOPE_RESERVE)
    for node in reads:
        source = node.outputs['Attribute']; consumers = [link.to_socket for link in source.links]
        q = c.V(g, source)
        effective = q*(1.-reserve*4.*q*(1.-q))
        for socket in consumers:
            g.bind(effective, socket)
    tree['st_corner_profile_slope_reserve'] = 1
    return tree


def with_depth_floor(root, *, minimum_ratio=.75, slope_reserve=0.):
    """Opt-in repair of existing capped-profile layouts, preserving other DAGs."""
    if not 0. <= slope_reserve <= .1:
        raise ValueError('Experimental slope reserve must be between zero and ten percent')
    memo = {}; changes = []
    def visit(tree):
        if tree.as_pointer() in memo:
            return memo[tree.as_pointer()]
        if tree.get('st_capped_profile_depth') and not tree.get('st_corner_depth_floor'):
            result = tree.copy(); result.name = 'Feasible depth layout / '+tree.name
            g = _graph(result)
            inp, = [node for node in result.nodes if node.type == 'GROUP_INPUT']
            correction, = [node for node in result.nodes if node.type == 'GROUP'
                           and node.label in ('Correct only reversed guide turns at mouths',
                                              'Correct full-band guides after rejected cells')]
            source = correction.outputs['Samples']; consumers = [link.to_socket for link in source.links]
            proposal = g.node('GeometryNodeGroup', 'Recover profile room after infeasible guide compression')
            proposal.node_tree = depth_floor(minimum_ratio=minimum_ratio)
            g.bind(source, proposal.inputs['Samples']); g.bind(inp.outputs['Mouths'], proposal.inputs['Mouths'])
            g.bind(c._read(g, inp.outputs['Plan'], 'st_cq_count', 0, 'INT'), proposal.inputs['Rows'])
            g.bind(correction.outputs['Applied'], proposal.inputs['Eligible'])
            for socket in consumers:
                g.bind(proposal.outputs['Samples'], socket)
            if slope_reserve:
                refined, = [node for node in result.nodes if node.type == 'GROUP'
                            and node.label == 'Conforming directional quads with exact entrance edges']
                source = refined.outputs['Geometry']; consumers = [link.to_socket for link in source.links]
                # Add this record only when depth recovery actually ran. An
                # already accepted layout retains all its numeric arrays.
                reserved = c._store(g, source, SLOPE_RESERVE, slope_reserve)
                reserved = c.choose(g, proposal.outputs['Applied'], reserved, source, 'GEOMETRY')
                for socket in consumers:
                    g.bind(reserved, socket)
            result['st_corner_depth_floor'] = minimum_ratio; changes.append(tree.name)
        elif slope_reserve and tree.get('st_height_profile_experiment'):
            result = reserved_slope_height(tree)
        else:
            children = [(node.name, visit(node.node_tree)) for node in tree.nodes
                        if node.type == 'GROUP' and node.node_tree]
            updates = [(name, child) for name, child in children if child != tree.nodes[name].node_tree]
            result = tree.copy() if updates else tree
            for name, child in updates:
                assign_group(result.nodes[name], child)
        memo[tree.as_pointer()] = result
        return result
    result = visit(root)
    if not changes:
        raise ValueError('No existing capped-profile guide layouts found')
    return result, sorted(set(changes))


def with_primary_depth_profile(root, *, minimum_ratio=.75, slope_reserve=0.):
    """Experimental physical-depth law on the primary equal-crown layout.

    Previously only the failed-cell retry measured physical band depth. A
    positive planar quad can also compress a full profile into too little
    space. Measure the primary layout too; retain its boundary and entrance
    rows, and use the existing bounded depth proposal only when the effective
    q would violate its .5 feasibility boundary (including a reserve). Unequal
    crowns and half profiles keep their existing construction. No geometry
    or profile admission is bypassed. Whole-gradient tests remain required.
    """
    from . import curved_quad_strip_refinement_nodes as refinement
    if not 0. <= slope_reserve <= .1:
        raise ValueError('Primary slope reserve must be between zero and ten percent')
    # The reserve changes the law's feasibility condition, not its acceptance
    # threshold. Solve its fixed scalar q_eff=.5 boundary once at build time.
    lo, hi = .5, 1.
    for _ in range(48):
        mid = .5*(lo+hi)
        if mid*(1.-slope_reserve*4.*mid*(1.-mid)) <= .5:lo = mid
        else:hi = mid
    trigger = hi+1e-6 if slope_reserve else .500001
    if minimum_ratio < trigger:
        raise ValueError('Requested primary depth cannot accommodate the slope reserve')
    memo = {}; changes = []; layouts = {}

    def primary(original):
        if original in layouts:return layouts[original]
        if original.get('st_capped_profile_depth') or original.get('st_primary_profile_depth'):
            raise ValueError('Primary depth profile already installed')
        result = original.copy(); result.name = 'Primary physical depth / '+original.name
        g = _graph(result)
        inp, = [node for node in result.nodes if node.type == 'GROUP_INPUT']
        loop, = [node for node in result.nodes if node.bl_idname == 'GeometryNodeRepeatInput'
                 and node.label.startswith('Prepare independent corner guides from physical boundary')]
        source = loop.paired_output.outputs['Geometry']
        consumers = [link.to_socket for link in source.links]
        mouths = inp.outputs['Mouths']
        equal = g.math('LESS_THAN', c._stat(g, mouths, c.named(g, 'st_cj_rise'), 'Max')
                       -c._stat(g, mouths, c.named(g, 'st_cj_rise'), 'Min'), 1e-7)
        eligible = equal*c._stat(g, mouths, g.math('COMPARE', c.named(g, 'st_cj_half', 'INT'), 0.))
        n = c._read(g, inp.outputs['Plan'], 'st_cq_count', 0, 'INT')
        proposal = g.node('GeometryNodeGroup', 'Recover insufficient primary profile depth')
        proposal.node_tree = depth_floor(minimum_ratio=minimum_ratio, trigger_ratio=trigger)
        for key, value in (('Samples', source), ('Mouths', mouths), ('Rows', n), ('Eligible', eligible)):
            g.bind(value, proposal.inputs[key])
        physical = g.node('GeometryNodeGroup', 'Measure primary equal-crown profile depth')
        physical.node_tree = depth_samples()
        for key, value in (('Samples', proposal.outputs['Samples']), ('Mouths', mouths), ('Rows', n)):
            g.bind(value, physical.inputs[key])
        for socket in consumers:g.bind(physical.outputs['Samples'], socket)
        refined, = [node for node in result.nodes if node.type == 'GROUP'
                    and node.label == 'Conforming directional quads with exact entrance edges']
        chart, row, col = g.separate(c.named(g, 'st_cq_key', 'FLOAT_VECTOR'))
        guide = g.math('COMPARE', chart, 0.)
        owner = c.choose(g, guide, row, chart-1.)
        station = c.choose(g, guide, col, row)
        ratio = c._read(g, physical.outputs['Samples'], ATTRIBUTE, owner*(n+1.)+station)
        active = eligible*g.math('MAXIMUM', guide, g.math('GREATER_THAN', chart, .5))
        ratio = c.choose(g, active, ratio, 1.)
        source = refined.inputs['Geometry'].links[0].from_socket
        g.bind(c._store(g, source, ATTRIBUTE, ratio), refined.inputs['Geometry'])
        settings = refinement.settings(refined.node_tree)
        if not settings['profile_records']:
            raise ValueError('Primary depth needs the existing forward-profile refinement records')
        settings['profile_depth'] = True
        refined.node_tree = refinement.build(**settings)
        if slope_reserve:
            source = refined.outputs['Geometry']; consumers = [link.to_socket for link in source.links]
            reserved = c._store(g, source, SLOPE_RESERVE, c.choose(g, eligible, slope_reserve, 0.))
            for socket in consumers:g.bind(reserved, socket)
        result['st_primary_profile_depth'] = minimum_ratio
        result['st_primary_profile_slope_reserve'] = slope_reserve
        layouts[original] = result; changes.append(original.name)
        return result

    def visit(tree):
        if tree.as_pointer() in memo:return memo[tree.as_pointer()]
        updates = []
        for node in tree.nodes:
            if node.type != 'GROUP' or not node.node_tree:continue
            child = (primary(node.node_tree) if tree.get('st_corner_guarded_retry')
                     and node.label == 'Original accepted corner layout' else visit(node.node_tree))
            if child != node.node_tree:updates.append((node.name, child))
        result = tree.copy() if updates else tree
        for name, child in updates:assign_group(result.nodes[name], child)
        memo[tree.as_pointer()] = result
        return result

    result = visit(root)
    if not changes:raise ValueError('No primary guarded ordinary layout found')
    return result, sorted(set(changes))
